"""等额本息贷款计算。"""


def _validate(principal, annual_rate, years):
    if principal <= 0:
        raise ValueError("本金必须大于 0")
    if annual_rate < 0:
        raise ValueError("年利率不能为负数")
    if years <= 0:
        raise ValueError("年限必须大于 0")


def monthly_payment(principal, annual_rate, years):
    """计算等额本息月供。

    annual_rate 为百分数，例如 4.9 表示 4.9%。
    """
    _validate(principal, annual_rate, years)
    months = int(years * 12)
    r = annual_rate / 100 / 12
    if r == 0:
        return principal / months
    factor = (1 + r) ** months
    return principal * r * factor / (factor - 1)


def total_interest(principal, annual_rate, years):
    """计算还款期内支付的总利息。"""
    months = int(years * 12)
    payment = monthly_payment(principal, annual_rate / 100, years)
    return payment * months - principal
